mapper.select:
        select
        mn.*,
        sf.file_Relation_Id as fileRelationId
        from pro_purchase mn
        left join sys_file sf on sf.fileId=mn.id
        where 1=1

        
            and mn.p_name like concat('%', #{params.pName}, '%')
        
        
            and mn.p_Id like concat('%', #{params.pId}, '%')
        
        
            and mn.project_Type = #{params.projectType}
        

        
            and mn.Purchase_Date >= #{params.filerTimeStart}
            and mn.Purchase_Date <= #{params.filerTimeEnd}
        
        
            
                order by mn.${params.sortFiled} ${params.sortType}
            
            
                order by ${params.sortSideFiled} ${params.sortType}
            
            
                order by mn.Create_Time DESC
